<?php
namespace Modules\Analytics\Controllers\Web;
use Core\http\ResponseFactory;use Modules\Analytics\Services\AdminProfileContentService;
final class AdminProfileContentController{public function __construct(private AdminProfileContentService$s){}public function index(string$entity){return$this->run(fn()=>$this->s->index((int)auth()->id(),$entity));}public function store(string$entity){return$this->run(fn()=>['id'=>$this->s->save((int)auth()->id(),$entity,null,$_POST)],201);}public function update(string$entity,int$id){return$this->run(fn()=>['id'=>$this->s->save((int)auth()->id(),$entity,$id,$_POST)]);}public function delete(string$entity,int$id){return$this->run(function()use($entity,$id){$this->s->delete((int)auth()->id(),$entity,$id);return null;});}public function status(string$entity,int$id){return$this->run(function()use($entity,$id){$this->s->cycleStatus((int)auth()->id(),$entity,$id);return null;});}public function vote(int$id){return$this->run(function()use($id){$this->s->vote((int)auth()->id(),$id,(array)($_POST['options']??[]));return null;});}private function run(callable$f,int$s=200){try{return ResponseFactory::json(['success'=>true,'data'=>$f()],$s);}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}}
